// PhotoFrame.js
import React, { useRef, useState, useEffect } from 'react';

const PhotoFrame = ({ photo, userName, location }) => {
  const canvasRef = useRef(null);
  const [photoUrl, setPhotoUrl] = useState(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    if (photo) {
      const url = URL.createObjectURL(photo);
      setPhotoUrl(url);
      return () => URL.revokeObjectURL(url);
    }
  }, [photo]);

  useEffect(() => {
    if (photoUrl) {
      drawFrame();
    }
    // eslint-disable-next-line
  }, [photoUrl, userName, location]);

  const drawFrame = async () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    // Canvas size
    const W = 1080;
    const H = 1450;
    canvas.width = W;
    canvas.height = H;

    // Colors
    const GREEN = '#0d5d36';
    const DARK_GREEN = '#08442a';
    const GOLD = '#c9a24a';
    const GOLD_LIGHT = '#e8c97a';
    const GOLD_DARK = '#9c7a2e';
    const CREAM = '#fdfaf2';

    // ---------- BACKGROUND (Green outer) ----------
    const bgGrad = ctx.createLinearGradient(0, 0, 0, H);
    bgGrad.addColorStop(0, GREEN);
    bgGrad.addColorStop(1, DARK_GREEN);
    ctx.fillStyle = bgGrad;
    ctx.fillRect(0, 0, W, H);

    // ---------- INNER CREAM PANEL ----------
    const inset = 55;
    const topRadius = 90;
    // The cream area ends here - everything BELOW will be on green
    const creamBottomY = 1010; // ribbon center area

    ctx.fillStyle = CREAM;
    ctx.beginPath();
    ctx.moveTo(inset, topRadius + inset);
    ctx.quadraticCurveTo(inset, inset, inset + topRadius, inset);
    ctx.lineTo(W - inset - topRadius, inset);
    ctx.quadraticCurveTo(W - inset, inset, W - inset, topRadius + inset);
    ctx.lineTo(W - inset, creamBottomY);
    // Curved bottom of cream area
    ctx.quadraticCurveTo(W / 2, creamBottomY + 90, inset, creamBottomY);
    ctx.closePath();
    ctx.fill();

    // ---------- GOLD BORDERS (rounded rectangle) ----------
    const drawRoundedFrame = (offset, lineWidth, strokeStyle) => {
      ctx.strokeStyle = strokeStyle;
      ctx.lineWidth = lineWidth;
      ctx.beginPath();
      const x = inset + offset;
      const y = inset + offset;
      const w = W - 2 * (inset + offset);
      const r = topRadius;
      ctx.moveTo(x, y + r);
      ctx.quadraticCurveTo(x, y, x + r, y);
      ctx.lineTo(x + w - r, y);
      ctx.quadraticCurveTo(x + w, y, x + w, y + r);
      ctx.lineTo(x + w, creamBottomY - offset);
      ctx.quadraticCurveTo(W / 2, creamBottomY + 90 - offset, x, creamBottomY - offset);
      ctx.closePath();
      ctx.stroke();
    };

    drawRoundedFrame(10, 2, GOLD);

    const goldGrad = ctx.createLinearGradient(0, 0, W, 0);
    goldGrad.addColorStop(0, GOLD_DARK);
    goldGrad.addColorStop(0.5, GOLD_LIGHT);
    goldGrad.addColorStop(1, GOLD_DARK);
    drawRoundedFrame(22, 5, goldGrad);

    // ---------- BOTTOM GOLD DECORATIVE CURVES ----------
    ctx.strokeStyle = goldGrad;
    ctx.lineWidth = 5;
    ctx.beginPath();
    ctx.moveTo(70, H - 145);
    ctx.quadraticCurveTo(W / 2, H - 35, W - 70, H - 145);
    ctx.stroke();

    ctx.strokeStyle = GOLD_LIGHT;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(95, H - 140);
    ctx.quadraticCurveTo(W / 2, H - 50, W - 95, H - 140);
    ctx.stroke();

    // =====================================================
    // CONTENT LAYOUT
    // =====================================================
    const Y_LOGO = 175;
    const Y_TITLE = 410;
    const Y_TITLE_LINE = 445;
    const Y_PHOTO = 700;
    const PHOTO_R = 200;
    const Y_RIBBON = 945; // ribbon position

    // ---------- 100 YEARS LOGO ----------
    drawHundredYearsLogo(ctx, W / 2, Y_LOGO, GREEN, GOLD, GOLD_LIGHT, GOLD_DARK);

    // ---------- LOCATION TITLE ----------
    ctx.fillStyle = DARK_GREEN;
    ctx.font = 'bold 60px "Times New Roman", serif';
    ctx.textAlign = 'center';
    ctx.fillText(location || 'Location', W / 2, Y_TITLE);

    drawOrnamentLine(ctx, W / 2, Y_TITLE_LINE, 320, GOLD);

    // ---------- CIRCULAR PHOTO ----------
    drawPhotoRings(ctx, W / 2, Y_PHOTO, PHOTO_R, GREEN, GOLD, GOLD_LIGHT, GOLD_DARK);

    if (photoUrl) {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.onload = () => {
        ctx.save();
        ctx.beginPath();
        ctx.arc(W / 2, Y_PHOTO, PHOTO_R, 0, Math.PI * 2);
        ctx.closePath();
        ctx.clip();
        const ratio = Math.max((PHOTO_R * 2) / img.width, (PHOTO_R * 2) / img.height);
        const dw = img.width * ratio;
        const dh = img.height * ratio;
        ctx.drawImage(img, W / 2 - dw / 2, Y_PHOTO - dh / 2, dw, dh);
        ctx.restore();

        drawSideOrnament(ctx, W / 2 - PHOTO_R - 38, Y_PHOTO, GOLD);
        drawSideOrnament(ctx, W / 2 + PHOTO_R + 38, Y_PHOTO, GOLD);

        finishDrawing();
      };
      img.src = photoUrl;
    } else {
      ctx.fillStyle = '#e5e7eb';
      ctx.beginPath();
      ctx.arc(W / 2, Y_PHOTO, PHOTO_R, 0, Math.PI * 2);
      ctx.fill();
      drawSideOrnament(ctx, W / 2 - PHOTO_R - 38, Y_PHOTO, GOLD);
      drawSideOrnament(ctx, W / 2 + PHOTO_R + 38, Y_PHOTO, GOLD);
      finishDrawing();
    }

    function finishDrawing() {
      // ---------- GIFT OF READING RIBBON (sits at edge of cream/green) ----------
      const ribbonW = 540;
      const ribbonH = 88;
      const rx = W / 2 - ribbonW / 2;
      const ry = Y_RIBBON;

      // Left tail
      ctx.fillStyle = DARK_GREEN;
      ctx.beginPath();
      ctx.moveTo(rx - 55, ry + 12);
      ctx.lineTo(rx + 18, ry + 8);
      ctx.lineTo(rx + 18, ry + ribbonH);
      ctx.lineTo(rx - 55, ry + ribbonH + 22);
      ctx.lineTo(rx - 28, ry + (ribbonH + 22) / 2);
      ctx.closePath();
      ctx.fill();

      // Right tail
      ctx.beginPath();
      ctx.moveTo(rx + ribbonW + 55, ry + 12);
      ctx.lineTo(rx + ribbonW - 18, ry + 8);
      ctx.lineTo(rx + ribbonW - 18, ry + ribbonH);
      ctx.lineTo(rx + ribbonW + 55, ry + ribbonH + 22);
      ctx.lineTo(rx + ribbonW + 28, ry + (ribbonH + 22) / 2);
      ctx.closePath();
      ctx.fill();

      // Main ribbon body
      ctx.fillStyle = GREEN;
      roundRect(ctx, rx, ry, ribbonW, ribbonH, 4);
      ctx.fill();

      // Inner gold border
      ctx.strokeStyle = GOLD_LIGHT;
      ctx.lineWidth = 2.5;
      roundRect(ctx, rx + 8, ry + 8, ribbonW - 16, ribbonH - 16, 3);
      ctx.stroke();

      // Ribbon text
      ctx.fillStyle = CREAM;
      ctx.font = 'italic bold 46px "Georgia", serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText('• Gift of Reading •', W / 2, ry + ribbonH / 2);
      ctx.textBaseline = 'alphabetic';

      // ===== TEXT ON GREEN AREA (below ribbon) =====
      // "Presented by" - on green, in light cream
      ctx.fillStyle = GOLD_LIGHT;
      ctx.font = 'italic 28px "Georgia", serif';
      ctx.textAlign = 'center';
      ctx.fillText('Presented by', W / 2, 1140);

      // small gold underline
      ctx.strokeStyle = GOLD;
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.moveTo(W / 2 - 60, 1155);
      ctx.lineTo(W / 2 + 60, 1155);
      ctx.stroke();

      // Location/School - on green, cream color
      ctx.fillStyle = CREAM;
      ctx.font = 'bold 34px "Georgia", serif';
      ctx.fillText(location || 'Location', W / 2, 1195);

      // Decorative ornament line
      drawNameOrnament(ctx, W / 2, 1255, 380, GOLD, GOLD_LIGHT);

      // User name - prominent
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 46px "Georgia", serif';
      ctx.fillText(userName || 'Participant', W / 2, 1320);

      // ---------- BOTTOM BOOK ICON ----------
      drawBookIcon(ctx, W / 2, H - 70, GOLD, GOLD_LIGHT);

      setIsReady(true);
    }
  };

  // ============= HELPERS ==============

  const drawHundredYearsLogo = (ctx, cx, cy, green, gold, goldLight, goldDark) => {
    // Stars on top
    [-1, 0, 1].forEach((i) => {
      drawStar(ctx, cx + i * 28, cy - 115, 7, gold);
    });

    // Laurel wreaths
    drawLaurel(ctx, cx - 145, cy - 10, gold, false);
    drawLaurel(ctx, cx + 145, cy - 10, gold, true);

    // "1" "0" "0" with proper spacing
    ctx.fillStyle = green;
    ctx.font = 'bold 110px "Georgia", serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    ctx.fillText('1', cx - 70, cy - 30);
    ctx.fillText('0', cx - 5, cy - 30);
    ctx.fillText('0', cx + 60, cy - 30);
    ctx.textBaseline = 'alphabetic';

    // Tiny book icon ABOVE digits between the zeros
    drawTinyBook(ctx, cx + 28, cy - 75, gold, goldLight);

    // YEARS text
    ctx.fillStyle = green;
    ctx.font = 'bold 22px "Georgia", serif';
    ctx.textAlign = 'center';
    ctx.fillText('YEARS', cx, cy + 38);

    // CELEBRATION ribbon
    const ribW = 200;
    const ribH = 32;
    const rx = cx - ribW / 2;
    const ry = cy + 55;

    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(rx, ry);
    ctx.lineTo(rx + ribW, ry);
    ctx.lineTo(rx + ribW + 14, ry + ribH / 2);
    ctx.lineTo(rx + ribW, ry + ribH);
    ctx.lineTo(rx, ry + ribH);
    ctx.lineTo(rx - 14, ry + ribH / 2);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = goldLight;
    ctx.fillRect(rx + 4, ry + 4, ribW - 8, 3);

    ctx.fillStyle = '#fff';
    ctx.font = 'bold 17px "Georgia", serif';
    ctx.textBaseline = 'middle';
    ctx.fillText('CELEBRATION', cx, ry + ribH / 2);
    ctx.textBaseline = 'alphabetic';

    drawOrnamentLine(ctx, cx, cy + 110, 130, gold);
  };

  const drawTinyBook = (ctx, cx, cy, gold, goldLight) => {
    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(cx - 24, cy);
    ctx.lineTo(cx, cy - 14);
    ctx.lineTo(cx + 24, cy);
    ctx.lineTo(cx, cy + 10);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = goldLight;
    ctx.beginPath();
    ctx.moveTo(cx - 20, cy - 1);
    ctx.lineTo(cx, cy - 11);
    ctx.lineTo(cx + 20, cy - 1);
    ctx.lineTo(cx, cy + 7);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 11);
    ctx.lineTo(cx, cy + 7);
    ctx.stroke();
  };

  const drawLaurel = (ctx, cx, cy, color, mirror) => {
    ctx.save();
    ctx.translate(cx, cy);
    if (mirror) ctx.scale(-1, 1);

    ctx.strokeStyle = color;
    ctx.fillStyle = color;
    ctx.lineWidth = 2.5;

    ctx.beginPath();
    ctx.moveTo(0, -75);
    ctx.quadraticCurveTo(-45, 0, 0, 75);
    ctx.stroke();

    for (let i = -65; i <= 65; i += 14) {
      const t = (i + 65) / 130;
      const x = -Math.sin(t * Math.PI) * 45;
      ctx.save();
      ctx.translate(x, i);
      ctx.rotate(-Math.PI / 4 - 0.2);
      ctx.beginPath();
      ctx.ellipse(-9, 0, 11, 4.5, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }
    ctx.restore();
  };

  const drawStar = (ctx, cx, cy, r, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    for (let i = 0; i < 5; i++) {
      const angle = (Math.PI * 2 * i) / 5 - Math.PI / 2;
      const x = cx + Math.cos(angle) * r;
      const y = cy + Math.sin(angle) * r;
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
      const angle2 = angle + Math.PI / 5;
      const x2 = cx + Math.cos(angle2) * (r / 2.3);
      const y2 = cy + Math.sin(angle2) * (r / 2.3);
      ctx.lineTo(x2, y2);
    }
    ctx.closePath();
    ctx.fill();
  };

  const drawOrnamentLine = (ctx, cx, cy, width, color) => {
    ctx.strokeStyle = color;
    ctx.lineWidth = 1.3;
    ctx.beginPath();
    ctx.moveTo(cx - width / 2, cy);
    ctx.lineTo(cx - 18, cy);
    ctx.moveTo(cx + 18, cy);
    ctx.lineTo(cx + width / 2, cy);
    ctx.stroke();

    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 6);
    ctx.lineTo(cx + 6, cy);
    ctx.lineTo(cx, cy + 6);
    ctx.lineTo(cx - 6, cy);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.arc(cx - 13, cy, 2, 0, Math.PI * 2);
    ctx.arc(cx + 13, cy, 2, 0, Math.PI * 2);
    ctx.fill();
  };

  const drawNameOrnament = (ctx, cx, cy, width, gold, goldLight) => {
    const g = ctx.createLinearGradient(cx - width / 2, 0, cx + width / 2, 0);
    g.addColorStop(0, 'rgba(232,201,122,0)');
    g.addColorStop(0.5, goldLight);
    g.addColorStop(1, 'rgba(232,201,122,0)');

    ctx.strokeStyle = g;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx - width / 2, cy);
    ctx.lineTo(cx - 25, cy);
    ctx.moveTo(cx + 25, cy);
    ctx.lineTo(cx + width / 2, cy);
    ctx.stroke();

    ctx.fillStyle = goldLight;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 8);
    ctx.lineTo(cx + 8, cy);
    ctx.lineTo(cx, cy + 8);
    ctx.lineTo(cx - 8, cy);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(cx - 18, cy - 4);
    ctx.lineTo(cx - 14, cy);
    ctx.lineTo(cx - 18, cy + 4);
    ctx.lineTo(cx - 22, cy);
    ctx.closePath();
    ctx.moveTo(cx + 18, cy - 4);
    ctx.lineTo(cx + 22, cy);
    ctx.lineTo(cx + 18, cy + 4);
    ctx.lineTo(cx + 14, cy);
    ctx.closePath();
    ctx.fill();
  };

  const drawSideOrnament = (ctx, cx, cy, color) => {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 11);
    ctx.lineTo(cx + 9, cy);
    ctx.lineTo(cx, cy + 11);
    ctx.lineTo(cx - 9, cy);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.arc(cx, cy - 18, 2.5, 0, Math.PI * 2);
    ctx.arc(cx, cy + 18, 2.5, 0, Math.PI * 2);
    ctx.fill();
  };

  const drawPhotoRings = (ctx, cx, cy, r, green, gold, goldLight, goldDark) => {
    ctx.strokeStyle = gold;
    ctx.lineWidth = 3;
    ctx.beginPath();
    ctx.arc(cx, cy, r + 32, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = goldDark;
    ctx.lineWidth = 2;
    ctx.setLineDash([2, 7]);
    ctx.beginPath();
    ctx.arc(cx, cy, r + 22, 0, Math.PI * 2);
    ctx.stroke();
    ctx.setLineDash([]);

    ctx.strokeStyle = green;
    ctx.lineWidth = 9;
    ctx.beginPath();
    ctx.arc(cx, cy, r + 8, 0, Math.PI * 2);
    ctx.stroke();

    ctx.strokeStyle = goldLight;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.arc(cx, cy, r + 2, 0, Math.PI * 2);
    ctx.stroke();
  };

  const drawBookIcon = (ctx, cx, cy, gold, goldLight) => {
    ctx.strokeStyle = gold;
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(cx - 110, cy + 3);
    ctx.quadraticCurveTo(cx - 85, cy - 8, cx - 60, cy + 3);
    ctx.moveTo(cx + 110, cy + 3);
    ctx.quadraticCurveTo(cx + 85, cy - 8, cx + 60, cy + 3);
    ctx.stroke();

    ctx.fillStyle = gold;
    ctx.beginPath();
    ctx.moveTo(cx - 55, cy - 5);
    ctx.lineTo(cx, cy - 22);
    ctx.lineTo(cx + 55, cy - 5);
    ctx.lineTo(cx + 55, cy + 22);
    ctx.lineTo(cx, cy + 12);
    ctx.lineTo(cx - 55, cy + 22);
    ctx.closePath();
    ctx.fill();

    ctx.fillStyle = goldLight;
    ctx.beginPath();
    ctx.moveTo(cx - 50, cy - 2);
    ctx.lineTo(cx, cy - 18);
    ctx.lineTo(cx + 50, cy - 2);
    ctx.lineTo(cx + 50, cy + 18);
    ctx.lineTo(cx, cy + 8);
    ctx.lineTo(cx - 50, cy + 18);
    ctx.closePath();
    ctx.fill();

    ctx.strokeStyle = gold;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(cx, cy - 18);
    ctx.lineTo(cx, cy + 8);
    ctx.stroke();
  };

  const roundRect = (ctx, x, y, w, h, r) => {
    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const link = document.createElement('a');
    link.download = `gift-of-reading-${(userName || 'frame').replace(/\s+/g, '-')}.png`;
    link.href = canvas.toDataURL('image/png');
    link.click();
  };

  return (
    <div style={{ textAlign: 'center', marginTop: 16 }}>
      <div
        style={{
          display: 'inline-block',
          maxWidth: '100%',
          borderRadius: 12,
          overflow: 'hidden',
          boxShadow: '0 20px 60px rgba(0,0,0,0.18)',
          background: '#fdfaf2'
        }}
      >
        <canvas
          ref={canvasRef}
          style={{
            display: 'block',
            width: '100%',
            maxWidth: 480,
            height: 'auto'
          }}
        />
      </div>

      <div style={{ marginTop: 24 }}>
        <button
          onClick={handleDownload}
          disabled={!isReady}
          style={{
            background: 'linear-gradient(135deg, #0d5d36 0%, #08442a 100%)',
            color: '#fff',
            border: 'none',
            padding: '14px 36px',
            borderRadius: 50,
            fontSize: '1rem',
            fontWeight: 600,
            cursor: isReady ? 'pointer' : 'not-allowed',
            opacity: isReady ? 1 : 0.6,
            boxShadow: '0 8px 20px rgba(13,93,54,0.3)',
            letterSpacing: '0.5px',
            transition: 'transform 0.2s'
          }}
          onMouseOver={(e) => isReady && (e.currentTarget.style.transform = 'translateY(-2px)')}
          onMouseOut={(e) => (e.currentTarget.style.transform = 'translateY(0)')}
        >
          ⬇ Download Frame
        </button>
      </div>
    </div>
  );
};

export default PhotoFrame;
